            {"Tüycük: beden ve yüz sabit, tüy rengi forma renginden gelir; ayakkabı, kafa bandı, bileklik ve raket değişir.","Feather Pal: body and face are fixed, the feather colour comes from the shirt colour; shoes, headband, wristband and racket change."},
            // 2026-11-08 arayüz turu (yasin: "açıklama alanları amatör, butonlarda taşan"): tarz kimliği ve hapları, sap çipleri, Görünüş başlığı.
            {"Görünüş","Look"},{"Orta saha","Mid-court"},{"Ücretsiz. Maç dışında istediğin an değiştir.","Free. Change it any time outside a match."},{"Her vuruşta aynı his; artı ve eksi yok.","Same feel on every shot; no pluses, no minuses."},{"Smaçla bitirir, nefesini de smaçla harcar.","Finishes with smashes and spends stamina on them."},{"Smaç hızı +%6","Smash speed +6%"},{"Enerji dolumu +%30","Energy charge +30%"},{"Sıçrayış smacı tam orta +%25","Jump smash sweet spot +25%"},{"Smaçta nefes +%35","Stamina per smash +35%"},{"Her topa uzanır, sonra çabuk toparlanır.","Reaches every shuttle and recovers fast."},{"Uzanma erişimi +%8","Lunge reach +8%"},{"Toparlanma %20 hızlı","Recovery 20% faster"},{"Smaç hızı −%10","Smash speed −10%"},{"Fileyi kapatır, arka sahada geç kalır.","Owns the net, late to the back court."},{"File önü tam orta +%30","Net sweet spot +30%"},{"Arka sahaya koşu −%10","Run to the back court −10%"},{"Slice ve aldatmayla rakibi ters köşeye yatırır.","Wrong-foots the opponent with slices and deception."},{"Slice ve aldatma +%30","Slice and deception +30%"},{"Tam orta penceresi −%10","Sweet-spot window −10%"},{"İnce","Thin"},{"Kontrol +3","Control +3"},{"Drive −3","Drive −3"},{"Bilek ve drive +3","Wrist and drive +3"},{"Kontrol −3","Control −3"},{"Nötr: artı ve eksi yok","Neutral: no plus, no minus"},{"Seviye istemez. Kalın sargı sapı yarım ölçü kalınlaştırır.","No level needed. A thick overgrip adds half a size."},{"Çubuklar ekipmandan gelir; 50 ortalamadır. Tarz ve görünüm çubukları değiştirmez.","Bars come from your gear; 50 is average. Style and look don't change them."},{"Seviye istemez.","No level needed."},{"Orta: güç ve kontrol dengede","Medium: power and control in balance"}};
        public static bool En { get { return Ayar.dil == "en"; } }

        static void Yukle()
        {
            if (d != null) return; d = new Dictionary<string, string>(); kalip = new List<KeyValuePair<Regex, string>>();
            var t = Resources.Load<TextAsset>("tr_en"); var o = t != null ? Json.Obj(Json.Parse(t.text)) : null;
            if (o != null) foreach (var kv in o) if (kv.Value is string) d[kv.Key] = (string)kv.Value;
            foreach (var kv in UNITY_EK) if (!d.ContainsKey(kv.Key)) d[kv.Key] = kv.Value;
            foreach (var kv in d)
                if (kv.Key.Contains("{0}"))
                {
                    string re = "^" + Regex.Replace(Regex.Escape(kv.Key), @"\\\{(\d+)}", m => "(?<p" + m.Groups[1].Value + ">.+?)") + "$";
                    try { kalip.Add(new KeyValuePair<Regex, string>(new Regex(re), kv.Value)); } catch { }
                }
            kalip.Sort((a, b) => b.Key.ToString().Length.CompareTo(a.Key.ToString().Length));   // uzun (daha belirli) kalıp önce
        }
        // HTML Tr(k, ...a): anahtar çevrilir, sonra {i} yer tutucuları doldurulur.
        // Ekran turu (2026-10-30 dil turu, yasin: "menülerde dillere göre butonları ve metinleri ... universal olmalı"): İngilizcede
        // sözlükte olmayan anahtarlar (koddan değişkenle gelen adlar dahil) toplanır, rapora yazılır. Oyunda kapalı.
        public static bool EksikTopla; public static readonly HashSet<string> Eksik = new HashSet<string>();
        public static string T(string k, params object[] a)
        {
            string v = k; if (En) { Yukle(); string e; if (d.TryGetValue(k, out e)) v = e; else if (EksikTopla && k != null && k.Length > 1 && Eksik.Count < 500 && Regex.IsMatch(k, "[a-zçğıöşü]", RegexOptions.IgnoreCase)) Eksik.Add(k); }
            if (a != null && a.Length > 0) v = YerTut(v, a);
            return v;
        }
        // {n} yer tutucuları (2026-11-10 inceleme, fikir 22:09 #4): Regex.Replace + lambda her çağrıda Match nesneleri ve kapanış
        // ayırıyordu; L.T argümanla OnGUI'de karede birçok kez çağrılıyor. Aynı kural elle: {rakam} dizin < a.Length ise değer,
        // değilse olduğu gibi kalır; "{" tek başına ya da rakamsız "{x}" dokunulmaz (Regex ile birebir).
        static readonly System.Text.StringBuilder ytSb = new System.Text.StringBuilder(128);
        static string YerTut(string v, object[] a)
        {
            if (v == null || v.IndexOf('{') < 0) return v;
            ytSb.Length = 0; int n = v.Length;
            for (int i = 0; i < n; i++)
            {
                char c = v[i];
                if (c == '{')
                {
                    int j = i + 1, idx = 0; bool rakam = false;
                    while (j < n && v[j] >= '0' && v[j] <= '9') { idx = idx * 10 + (v[j] - '0'); rakam = true; j++; if (idx > 100000) break; }
                    if (rakam && j < n && v[j] == '}' && idx < a.Length) { ytSb.Append(System.Convert.ToString(a[idx])); i = j; continue; }
                }
                ytSb.Append(c);
            }
            return ytSb.ToString();
        }
        // Core'dan gelen bitmiş cümle: önce tam anahtar, sonra yer tutuculu kalıp; parçalar da (ör. görev adı) çevrilir.
        public static string Cumle(string s)
        {
            if (!En || string.IsNullOrEmpty(s)) return s; Yukle(); string e;
            if (d.TryGetValue(s, out e)) return e;
            foreach (var kv in kalip)
            {
                var m = kv.Key.Match(s); if (!m.Success) continue;
                return Regex.Replace(kv.Value, @"\{(\d+)\}", mm => { var g = m.Groups["p" + mm.Groups[1].Value]; return g.Success ? Cumle(g.Value) : mm.Value; });
            }
            // "A · B" ve "A: B" gibi birleşik cümleler parça parça
            if (s.Contains(" · ")) { var p = s.Split(new[] { " · " }, System.StringSplitOptions.None); for (int i = 0; i < p.Length; i++) p[i] = Cumle(p[i]); return string.Join(" · ", p); }
            return s;
        }
    }
